<script lang="ts">import {page} from '$app/state';import {goto} from '$app/navigation';import {auth} from '$lib/api';import TopNav from '$lib/components/TopNav.svelte';let password=$state(''),confirm=$state(''),error=$state(''),message=$state(''),loading=$state(false);async function submit(){if(password.length<8){error='Password must be at least 8 characters.';return}if(password!==confirm){error='Passwords do not match.';return}loading=true;error='';try{await auth.resetPassword(page.params.token||'',password);message='Your password has been reset. You can now log in.';setTimeout(()=>goto('/auth/login'),1200)}catch(e){error=e instanceof Error?e.message:'Unable to reset password.'}finally{loading=false}}</script><svelte:head><title>Set New Password · RegenFeed</title></svelte:head><TopNav/><main class="stitch-auth stitch-register"><form class="stitch-card" onsubmit={(e)=>{e.preventDefault();submit()}}><div class="stitch-heading"><h1>Set a new password</h1><p>Choose a strong password for your RegenFeed account.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if message}<p class="success" role="status">{message}</p>{/if}<label>New Password<div class="stitch-input"><input bind:value={password} type="password" autocomplete="new-password" minlength="8" required /></div></label><label>Confirm Password<div class="stitch-input"><input bind:value={confirm} type="password" autocomplete="new-password" minlength="8" required /></div></label><button class="stitch-button" disabled={loading}>{loading?'Saving…':'Save new password'} <i class="fa-solid fa-check"></i></button></form></main>
